using System;
using System.Collections.Generic;
using System.Linq;

namespace RunicAutomation
{
    // Each Runic plugin embeds its own build of Shared/InventorySafety, and the first plugin to
    // touch a SharedState key owns that service for every later plugin (SharedOperationHost,
    // InventoryOperationNetwork, NativeChestInterop patches, ...). Nothing else checks that the
    // copies were built from the same source, so mixed module versions would quietly run one
    // module's host with another module's patches. Every plugin registers the hash generated by
    // EmbeddedCore.targets; disagreement keeps the inventory authority from ever reporting ready,
    // so every module falls back to native handling instead of running a version mix.
    internal static class EmbeddedCoreAgreement
    {
        private const string Key = "operations.embedded-core.v1";
        private const string ReportedKey = "operations.embedded-core.reported.v1";
        internal static string Hash => EmbeddedCore.Hash;
        internal static string ShortHash => Hash.Length > 12 ? Hash.Substring(0, 12) : Hash;

        private static Dictionary<string, string> Registry => SharedState.Get(Key, () => new Dictionary<string, string>());

        // Static methods compile into the calling plugin, so EmbeddedCore.Hash is always the
        // caller's own build even when another plugin owns the shared dictionaries.
        internal static void Register(string module)
        {
            if (string.IsNullOrEmpty(module)) throw new ArgumentException("A module name is required.", nameof(module));
            var registry = Registry;
            lock (SharedState.Sync) registry[module] = Hash;
        }

        internal static bool Agree
        {
            get
            {
                var registry = Registry;
                lock (SharedState.Sync) return registry.Values.Distinct(StringComparer.Ordinal).Count() <= 1;
            }
        }

        internal static string Describe()
        {
            var registry = Registry;
            lock (SharedState.Sync)
                return string.Join(", ", registry.OrderBy(x => x.Key, StringComparer.Ordinal)
                    .Select(x => x.Key + "=" + (x.Value.Length > 12 ? x.Value.Substring(0, 12) : x.Value)));
        }

        // Logs the mismatch once per process. Returns false while the loaded modules disagree.
        internal static bool Verify()
        {
            if (Agree) return true;
            var reported = SharedState.Get(ReportedKey, () => new List<string>());
            bool first;
            lock (SharedState.Sync) { first = reported.Count == 0; if (first) reported.Add(Describe()); }
            if (first)
                UnityEngine.Debug.LogError("Runic modules were built from different embedded cores (" + Describe() +
                    "). Runic inventory transactions are disabled on this game until every installed Runic module is updated to the same release. Vanilla inventory handling remains active.");
            return false;
        }
    }
}
